// src/components/AiclientRoutes.jsx (새로운 파일)

import { Routes, Route, Outlet } from 'react-router-dom';
import Login from '@app/login/page'; // /login 페이지 컴포넌트 경로

function AiclientLayout() {
  return (
    <div>
      {/* 이 부분이 공통 레이아웃이 될 수 있습니다. */}
      <Outlet />
    </div>
  );
}

export default function AiclientRoutes() {
  return (
    <Routes>
      <Route path="/" element={<AiclientLayout />}>
        <Route path="login" element={<Login />} />
        {/* 필요한 다른 경로들 (예: /aiclient/:companyCode/dashboard) */}
        {/* <Route path="dashboard" element={<DashboardPage />} /> */}
      </Route>
    </Routes>
  );
}
